use loomward_catalog::*;
use rusqlite::Connection;
use serde_json::json;
use std::time::Instant;
fn listing(w: &Writer, run: i64, dir: i64, refresh: bool, rows: usize) -> Result<()> {
    for (seq, start) in (0..rows).step_by(1000).enumerate() {
        let files = (start..rows.min(start + 1000))
            .filter(|i| !refresh || *i != 0)
            .map(|i| {
                let mut o = Observation::file(
                    format!("synthetic-{i:07}.dat"),
                    100 + u64::from(refresh),
                    Some(4096),
                );
                o.file_id = Some((if i == 0 { 1 } else { i } as u128).to_le_bytes().to_vec());
                o.created_ft = Some(42);
                o.extension = Some("dat".into());
                o.family = "data".into();
                o
            })
            .collect();
        w.call(WriteCommand::StageChunk {
            run_id: run,
            dir_id: dir,
            seq: seq as i64,
            files,
            dirs: vec![],
        })?;
    }
    w.call(WriteCommand::ListingDone {
        run_id: run,
        dir_id: dir,
        outcome: ListingOutcome::Complete,
        skipped: 0,
        errors: 0,
    })?;
    Ok(())
}
fn main() -> std::result::Result<(), Box<dyn std::error::Error>> {
    let rows = 100000usize;
    let temp = tempfile::tempdir()?;
    let c = Catalog::open(temp.path(), "synthetic")?;
    let w = c.writer();
    let WriteReply::Root {
        grant_id, dir_id, ..
    } = w.call(WriteCommand::RegisterRoot(RootObservation {
        volume_key: "fixture".into(),
        display_name: "Synthetic".into(),
        display_path: "Synthetic root".into(),
        root_file_id: Some(vec![255; 16]),
        filesystem: Some("NTFS".into()),
        origin: "fixture".into(),
        granted_via: "fixture".into(),
        observed_at_ns: 0,
    }))?
    else {
        unreachable!()
    };
    let begin = || {
        w.call(WriteCommand::BeginRun {
            grant_id,
            mode: "refresh".into(),
            strategy: "fixture".into(),
            started_at_ns: 0,
        })
    };
    let WriteReply::Run(run) = begin()? else {
        unreachable!()
    };
    listing(w, run, dir_id, false, rows)?;
    w.call(WriteCommand::EndRun {
        run_id: run,
        state: "completed".into(),
        finished_at_ns: 1,
    })?;
    let db = Connection::open(temp.path().join("catalog.db"))?;
    let file = db.query_row(
        "SELECT id FROM file WHERE name='synthetic-0000000.dat'",
        [],
        |r| r.get(0),
    )?;
    let survivor: i64 = db.query_row(
        "SELECT id FROM file WHERE name='synthetic-0000001.dat'",
        [],
        |r| r.get(0),
    )?;
    let WriteReply::Reference(reference) = w.call(WriteCommand::ObjectReference {
        node: NodeKey::File(file),
        observed_at_ns: 2,
    })?
    else {
        unreachable!()
    };
    let before = serde_json::to_value(w.timings())?;
    let WriteReply::Run(run) = begin()? else {
        unreachable!()
    };
    let started = Instant::now();
    listing(w, run, dir_id, true, rows)?;
    let seconds = started.elapsed().as_secs_f64();
    let after = serde_json::to_value(w.timings())?;
    let phases = after
        .as_object()
        .unwrap()
        .iter()
        .filter_map(|(k, v)| Some((k.clone(), json!(v.as_f64()? - before[k].as_f64()?))))
        .collect::<serde_json::Map<String, serde_json::Value>>();
    let state = Connection::open(temp.path().join("state.db"))?;
    assert_eq!(
        state.query_row(
            "SELECT row_id FROM object_ref WHERE id=?1 AND state='resolved' AND retired=0",
            [reference],
            |r| r.get::<_, i64>(0)
        )?,
        survivor
    );
    assert_eq!(
        state.query_row("SELECT count(*) FROM pending_reference", [], |r| r
            .get::<_, i64>(0))?,
        0
    );
    assert_eq!(
        db.query_row("SELECT count(*),sum(logical) FROM file", [], |r| Ok((
            r.get::<_, i64>(0)?,
            r.get::<_, i64>(1)?
        )))?,
        ((rows - 1) as i64, ((rows - 1) * 101) as i64)
    );
    println!(
        "{}",
        json!({"scope":"100k single-directory synthetic refresh, one durable reference rebounds to surviving hard link; shared host", "rows":rows-1,"seconds":seconds,"rows_per_second":(rows-1) as f64/seconds,"phases":phases,"oracle":true})
    );
    Ok(())
}

